<?php
require __DIR__ . '/bootstrap.php';

function icon_for(string $domain): string {
    return 'https://www.google.com/s2/favicons?sz=128&domain=' . rawurlencode($domain);
}

function site_item(string $name, string $url, ?string $domain = null): array {
    $host = $domain ?: parse_url($url, PHP_URL_HOST) ?: $url;
    return [
        'name' => $name,
        'url' => $url,
        'type' => 'SITE',
        'icon' => icon_for($host),
        'hasBorder' => false,
        'isNew' => false,
        'badge' => null
    ];
}

