foreach ($catalog as $category) {
    $links = [];
    foreach ($category['links'] as $link) {
        $links[] = site_item($link['name'], $link['url'], $link['domain'] ?? null);
    }
    $contents[] = [
        'id' => $category['id'],
        'category' => $category['category'],
